  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import type Player from '@vimeo/player';
  5→
  6→/**
  7→ * PROJECT HERO REEL - Project Page Autoplay Video
  8→ *
  9→ * Mirrors homepage HeroReel behavior with:
 10→ * - Fixed position at top (70vh desktop, 50vh mobile)
 11→ * - Cinematic fade-in entrance with subtle scale
 12→ * - Scroll-based fade out and pause/resume
 13→ * - NO thumbnail overlay (pure video, background mode)
 14→ * - Mobile optimization: static thumbnail only (no video player)
 15→ *
 16→ * Consistency guarantees:
 17→ * 1. Deterministic initialization with timeout (12s max)
 18→ * 2. Clean error handling with fallback to static state
 19→ * 3. Proper cleanup on unmount
 20→ * 4. Scroll-based pause/resume with ref tracking
 21→ * 5. Mobile optimization: static thumbnail only (no video player)
 22→ * 6. Error event listeners for runtime failures
 23→ */
 24→
 25→// Timeout for player initialization (12 seconds - supports slow connections)
 26→const INIT_TIMEOUT_MS = 12000;
 27→
 28→// Mobile detection hook - touch devices OR narrow viewports
 29→// Returns { isMobile, isReady } to prevent video initialization race condition
 30→function useIsMobile(): { isMobile: boolean; isReady: boolean } {
 31→  const [isMobile, setIsMobile] = useState(true); // Default to mobile (safer)
 32→  const [isReady, setIsReady] = useState(false);
 33→
 34→  useEffect(() => {
 35→    const checkMobile = () => {
 36→      const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
 37→      const isNarrowViewport = window.innerWidth < 768;
 38→      setIsMobile(isTouchDevice || isNarrowViewport);
 39→    };
 40→
 41→    checkMobile();
 42→    setIsReady(true); // Now we know for sure
 43→    window.addEventListener('resize', checkMobile);
 44→    return () => window.removeEventListener('resize', checkMobile);
 45→  }, []);
 46→
 47→  return { isMobile, isReady };
 48→}
