 50→interface ProjectHeroReelProps {
 51→  videoId: string;
 52→  videoHash?: string;
 53→  startTime?: number;
 54→  thumbnail?: string;
 55→}
 56→
 57→export function ProjectHeroReel({ videoId, videoHash, startTime = 0, thumbnail }: ProjectHeroReelProps) {
 58→  const containerRef = useRef<HTMLDivElement>(null);
 59→  const playerRef = useRef<Player | null>(null);
 60→  const isReadyRef = useRef(false);
 61→  const scrolledDownRef = useRef(false);
 62→
 63→  const [scrollProgress, setScrollProgress] = useState(0);
 64→  const [heroRevealed, setHeroRevealed] = useState(false);
 65→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
 66→
 67→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 68→
 69→  // Thumbnail URL - use provided thumbnail or fallback to Vimeo vumbnail
 70→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
 71→
 72→  // Hero height based on device
 73→  const heroHeight = isMobile ? '50vh' : '70vh';
 74→
 75→  // Clean destroy of player instance
 76→  const destroyPlayer = useCallback(() => {
 77→    if (playerRef.current) {
 78→      try {
 79→        playerRef.current.destroy();
 80→      } catch {
 81→        // Player may already be destroyed
 82→      }
 83→      playerRef.current = null;
 84→    }
 85→    isReadyRef.current = false;
 86→  }, []);
 87→
 88→  // Check reduced motion preference
 89→  useEffect(() => {
 90→    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
 91→    setPrefersReducedMotion(mediaQuery.matches);
 92→    const handleChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
 93→    mediaQuery.addEventListener('change', handleChange);
 94→    return () => mediaQuery.removeEventListener('change', handleChange);
 95→  }, []);
 96→
 97→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 98→  useEffect(() => {
 99→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
100→    return () => clearTimeout(revealTimer);
101→  }, []);
102→
103→  // Initialize Vimeo player with autoplay (desktop only)
104→  useEffect(() => {
105→    // Wait for mobile detection to complete before deciding
106→    if (!isMobileReady) return;
107→
108→    // Skip player initialization on mobile - use static thumbnail instead
109→    if (isMobile) return;
110→
111→    if (!containerRef.current) return;
112→
113→    const baseConfig = {
114→      muted: true,
115→      loop: true,
116→      autoplay: true,
117→      controls: false,
118→      background: true,
119→      responsive: true,
120→      title: false,
121→      byline: false,
122→      portrait: false,
123→      dnt: true,
124→      playsinline: true,
125→      quality: 'auto',
126→      speed: true,
127→    };
128→
129→    const baseUrl = videoHash
130→      ? `https://vimeo.com/${videoId}/${videoHash}`
131→      : `https://vimeo.com/${videoId}`;
132→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
133→
134→    let isMounted = true;
135→
136→    const initPlayer = async () => {
137→      try {
138→        const { default: VimeoPlayer } = await import('@vimeo/player');
139→        if (!isMounted || !containerRef.current) return;
140→
141→        playerRef.current = new VimeoPlayer(containerRef.current!, {
142→          url: urlWithTime as `https://vimeo.com/${string}`,
143→          ...baseConfig
144→        });
145→
146→        // Race between ready() and timeout
147→        const readyPromise = playerRef.current.ready();
148→        const timeoutPromise = new Promise<never>((_, reject) => {
149→          setTimeout(() => reject(new Error('ProjectHeroReel initialization timeout')), INIT_TIMEOUT_MS);
150→        });
151→
152→        await Promise.race([readyPromise, timeoutPromise]);
153→
154→        if (!isMounted) {
155→          destroyPlayer();
156→          return;
157→        }
158→
159→        isReadyRef.current = true;
160→
161→        // Add error event listener for runtime failures
162→        playerRef.current.on('error', (error) => {
163→          console.error('ProjectHeroReel: Player error', videoId, error);
164→          // Don't destroy - let video degrade gracefully to thumbnail
165→        });
166→
167→        // Start playback
168→        await playerRef.current.play().catch(() => {
169→          // Autoplay blocked - video will show loading state
170→        });
171→      } catch (err) {
172→        console.error('ProjectHeroReel: Player init failed', videoId, err);
173→        destroyPlayer();
174→      }
175→    };
176→
177→    initPlayer();
178→
179→    return () => {
180→      isMounted = false;
181→      destroyPlayer();
182→    };
183→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
184→
185→  // Track scroll for fade and pause/resume
186→  useEffect(() => {
187→    const handleScroll = () => {
188→      const scrollY = window.scrollY;
189→      const viewportHeight = window.innerHeight;
190→      // Use appropriate hero height multiplier based on device
191→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
192→
193→      // Fade out over 300px starting when content appears
194→      const fadeStartScroll = heroHeightValue * 0.3;
195→      const fadeRange = 300;
196→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
197→      setScrollProgress(progress);
198→
199→      // Pause/resume with ref tracking for consistency (desktop only)
200→      if (!isMobile) {
201→        const hasScrolledDown = scrollY > 10;
202→
203→        if (hasScrolledDown && !scrolledDownRef.current) {
204→          scrolledDownRef.current = true;
205→          if (playerRef.current && isReadyRef.current) {
206→            playerRef.current.pause().catch(() => {});
207→          }
208→        } else if (!hasScrolledDown && scrolledDownRef.current) {
209→          scrolledDownRef.current = false;
210→          if (playerRef.current && isReadyRef.current) {
211→            playerRef.current.play().catch(() => {});
212→          }
213→        }
214→      }
215→    };
216→
217→    // Run immediately to sync initial state
218→    handleScroll();
219→
220→    window.addEventListener('scroll', handleScroll, { passive: true });
221→    return () => window.removeEventListener('scroll', handleScroll);
222→  }, [isMobile]);
223→
224→  const scrollOpacity = 1 - scrollProgress;
225→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
226→  const heroScale = heroRevealed ? 1 : 1.02;
227→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
228→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
229→
230→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
231→  // This ensures scroll-driven fade is perfectly synchronized with navigation
232→  const heroTransition = heroRevealed
233→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
234→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
235→
236→  return (
237→    <div
238→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
239→      style={{
240→        height: heroHeight,
241→        zIndex: 0,
242→        backgroundColor: '#141414'
243→      }}
244→    >
245→      <div
246→        style={{
247→          width: '100%',
248→          height: '100%',
249→          opacity: heroOpacity,
250→          transform: `scale(${heroScale})`,
251→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
252→          transition: heroTransition,
253→          transformOrigin: 'center center',
254→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
255→        }}
256→      >
257→        {isMobile ? (
258→          // Mobile: Static thumbnail only (no video player)
259→          <div
260→            className="absolute inset-0 w-full h-full"
261→            style={{
262→              backgroundImage: `url(${thumbnailUrl})`,
263→              backgroundSize: 'cover',
264→              backgroundPosition: 'center',
265→              backgroundColor: '#141414',
266→              zIndex: 0
267→            }}
268→          />
269→        ) : (
270→          // Desktop: Vimeo player container
271→          <div
272→            ref={containerRef}
273→            className="absolute inset-0 w-full h-full"
274→            style={{
275→              backgroundColor: '#141414',
276→              zIndex: 0
277→            }}
278→          />
279→        )}
280→      </div>
281→    </div>
282→  );
283→}
